import type { AppEnvironment } from '#/lib/app-environment'

/**
 * What the page's `<head>` gives the browser and the home screen, per
 * environment (#454): staging links its own manifest (own name, yellow
 * icons), yellow icons and a yellow `theme-color`, so an install of it never
 * passes for production's. Production's are the files it always had. The
 * icons are generated by `pnpm --filter @finances/web icons` and precached
 * (`sw/precache.ts`) in both sets.
 */
export interface EnvironmentHead {
  /** `application-name` and `apple-mobile-web-app-title`. */
  appName: string
  manifest: string
  favicon: string
  /** SVG favicon, preferred by browsers that take one; none on staging. */
  svgIcon: string | null
  appleTouchIcon: string
  /** `theme-color` for the light and dark colour schemes. */
  themeColor: { light: string; dark: string }
}

export const ENVIRONMENT_HEAD: Record<AppEnvironment, EnvironmentHead> = {
  production: {
    appName: 'Capi',
    manifest: '/manifest.json',
    favicon: '/favicon.ico',
    // The mark as large as the tab allows, light on a dark tab bar.
    svgIcon: '/brand/capi-favicon.svg',
    appleTouchIcon: '/icons/apple-touch-icon.png',
    // Light and dark `--background` (`@finances/ui/globals.css`).
    themeColor: { light: '#f4f7fc', dark: '#090c1a' },
  },
  staging: {
    // The manifest's `short_name`: under the icon on the home screen.
    appName: 'Capi β',
    manifest: '/manifest-staging.json',
    favicon: '/icons/staging/favicon.ico',
    // The logo alone would look like production's tab.
    svgIcon: null,
    appleTouchIcon: '/icons/staging/apple-touch-icon.png',
    // Light and dark `--env-banner`, the colour of the header.
    themeColor: { light: '#f9d544', dark: '#e3b831' },
  },
}
